 * uses /raw/upload instead of /image/upload. That avoids 401 blocks from
 * Cloudinary's "Restricted media types" setting, which refuses to serve
 * non-image content under the image/upload path.
 */
export async function uploadRawToCloudinary(dataUri, options = {}) {
  const { folder = `${ROOT_FOLDER}/uploads`, ...rest } = options;
  const result = await cloudinary.uploader.upload(dataUri, {
    folder,
    resource_type: "raw",
    ...rest,
  });
  return result.secure_url;
}

